    }
    )
    }
    

    override fun `sameWordRound`(`words`: List<GameWord>, `rng`: kotlin.ULong): Prompts {
            return FfiConverterTypePrompts.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_polingual_core_fn_method_deck_same_word_round(
        it, FfiConverterSequenceTypeGameWord.lower(`words`),FfiConverterULong.lower(`rng`),_status)
