    }
    )
    }
    

    override fun `shared`(): List<kotlin.String> {
            return FfiConverterSequenceString.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_polingual_core_fn_method_deck_shared(
