sealed class Access {
    
    object Checking : Access()
    
    
    object Locked : Access()
    
    
    data class Trial(
        val `productId`: kotlin.String, 
        val `untilMs`: kotlin.Long?) : Access() {
        companion object
    }
    
    data class Subscribed(
        val `productId`: kotlin.String, 
        val `untilMs`: kotlin.Long?) : Access() {
        companion object
    }
    
    object Beta : Access()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAccess : FfiConverterRustBuffer<Access>{
    override fun read(buf: ByteBuffer): Access {
        return when(buf.getInt()) {
            1 -> Access.Checking
            2 -> Access.Locked
            3 -> Access.Trial(
                FfiConverterString.read(buf),
                FfiConverterOptionalLong.read(buf),
                )
            4 -> Access.Subscribed(
                FfiConverterString.read(buf),
                FfiConverterOptionalLong.read(buf),
                )
            5 -> Access.Beta
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Access) = when(value) {
        is Access.Checking -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Access.Locked -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Access.Trial -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`productId`)
                + FfiConverterOptionalLong.allocationSize(value.`untilMs`)
            )
        }
        is Access.Subscribed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`productId`)
                + FfiConverterOptionalLong.allocationSize(value.`untilMs`)
            )
        }
        is Access.Beta -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: Access, buf: ByteBuffer) {
        when(value) {
            is Access.Checking -> {
                buf.putInt(1)
                Unit
            }
            is Access.Locked -> {
                buf.putInt(2)
                Unit
            }
            is Access.Trial -> {
                buf.putInt(3)
                FfiConverterString.write(value.`productId`, buf)
                FfiConverterOptionalLong.write(value.`untilMs`, buf)
                Unit
            }
            is Access.Subscribed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`productId`, buf)
                FfiConverterOptionalLong.write(value.`untilMs`, buf)
                Unit
            }
            is Access.Beta -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





